// ============ Args parsing ============
bool isFlagArg(const string& name) {
    return name=="-saveOutput" || name=="-retrain" || name=="-qnorm" || name=="-qout";
}
bool isValidArg(const string& name) {
    static unordered_set<string> valid = {"-input","-output","-verbose","-minCount","-minCountLabel","-wordNgrams","-bucket","-minn","-maxn","-t","-label","-lr","-lrUpdateRate","-dim","-ws","-epoch","-neg","-loss","-thread","-pretrainedVectors","-saveOutput","-seed","-autotune-validation","-autotune-metric","-autotune-predictions","-autotune-duration","-autotune-modelsize","-cutoff","-retrain","-qnorm","-qout","-dsub"};
    return valid.count(name);
}

int parseArgs(const string& cmd, int argc, char** argv, Args& args) {
    // argv[0]=prog, argv[1]=cmd, rest are args
    // Returns 0 on success, 1 on help/error (already printed), throws on stof/stoi etc.
    Args defaults = getDefaults(cmd);
    args = defaults;
    args.model = defaults.model;
    // Collect tokens after cmd
    vector<string> toks;
    for (int i=2;i<argc;i++) toks.push_back(argv[i]);
    // Parse
    for (size_t i=0;i<toks.size();) {
        string a = toks[i];
        if (a.empty() || a[0]!='-') {
            printTrainHelp(cmd, "Provided argument without a dash! Usage:");
            return 1;
        }
        if (!isValidArg(a)) {
            printTrainHelp(cmd, "Unknown argument: "+a);
            return 1;
        }
        if (isFlagArg(a)) {
            if (a=="-saveOutput") args.saveOutput=true;
            else if (a=="-retrain") args.retrain=true;
            else if (a=="-qnorm") args.qnorm=true;
            else if (a=="-qout") args.qout=true;
            i++;
        } else {
            if (i+1>=toks.size()) {
                printTrainHelp(cmd, a+" is missing an argument");
                return 1;
            }
            string v = toks[i+1];
            if (a=="-input") args.input=v;
            else if (a=="-output") args.output=v;
            else if (a=="-verbose") args.verbose=stoi(v);
            else if (a=="-minCount") args.minCount=stoi(v);
            else if (a=="-minCountLabel") args.minCountLabel=stoi(v);
            else if (a=="-wordNgrams") args.wordNgrams=stoi(v);
            else if (a=="-bucket") args.bucket=stoi(v);
            else if (a=="-minn") args.minn=stoi(v);
            else if (a=="-maxn") args.maxn=stoi(v);
            else if (a=="-t") args.t=stof(v);
            else if (a=="-label") args.label=v;
            else if (a=="-lr") args.lr=stof(v);
            else if (a=="-lrUpdateRate") args.lrUpdateRate=stoi(v);
            else if (a=="-dim") args.dim=stoi(v);
            else if (a=="-ws") args.ws=stoi(v);
            else if (a=="-epoch") args.epoch=stoi(v);
            else if (a=="-neg") args.neg=stoi(v);
            else if (a=="-loss") args.loss=v;
            else if (a=="-thread") args.thread=stoi(v);
            else if (a=="-pretrainedVectors") args.pretrainedVectors=v;
            else if (a=="-seed") args.seed=stoi(v);
            else if (a=="-autotune-validation") args.autotuneValidation=v;
            else if (a=="-autotune-metric") args.autotuneMetric=v;
            else if (a=="-autotune-predictions") args.autotunePredictions=stoi(v);
            else if (a=="-autotune-duration") args.autotuneDuration=stoi(v);
            else if (a=="-autotune-modelsize") {
                // Validate model size: empty or parseable like 100k, 10M, etc.
                if (!v.empty()) {
                    // Try to parse: number + optional k/m/g suffix?
                    // Original error: "Unable to parse model size X"
                    string num = v;
                    char suffix = 0;
                    if (!num.empty() && (num.back()=='k'||num.back()=='K'||num.back()=='m'||num.back()=='M'||num.back()=='g'||num.back()=='G')) {
                        suffix=num.back(); num=num.substr(0,num.size()-1);
                    }
                    try {
                        // Try stoi/stod? Original likely uses stoi for number part?
                        // If fails, throw invalid_argument with custom message
                        size_t pos=0;
                        stoll(num, &pos);
                        if (pos!=num.size()) throw invalid_argument("");
                    } catch (...) {
                        throw invalid_argument("Unable to parse model size "+v);
                    }
                }
                args.autotuneModelsize=v;
            }
            else if (a=="-cutoff") args.cutoff=stoi(v);
            else if (a=="-dsub") args.dsub=stoi(v);
            i+=2;
        }
    }
    // Validate loss
    if (args.loss!="ns" && args.loss!="hs" && args.loss!="softmax" && args.loss!="one-vs-all") {
        printTrainHelp(cmd, "Unknown loss: "+args.loss);
        return 1;
    }
    // Validate autotune metric if validation set? Actually original validates metric even without validation? Let's see: autotune-metric foo without validation gave runtime_error. So validate always if metric != default? Actually default f1 is valid. If metric is not f1 and not f1:... then error.
    // Check: metric must be "f1" or "f1:label"
    {
        string m = args.autotuneMetric;
        if (m!="f1" && !(m.size()>3 && m.substr(0,3)=="f1:")) {
            throw runtime_error("Unknown metric : "+m);
        }
    }
    // Check empty input/output
    if (args.input.empty() || args.output.empty()) {
        if (cmd=="quantize" && toks.empty()) {
            printTrainHelp(cmd, "usage: fasttext quantize <args>");
            return 1;
        } else {
            printTrainHelp(cmd, "Empty input or output path.");
            return 1;
        }
    }
    return 0;
}

