// ============ Dictionary ============
struct Entry {
    string word;
    int64_t count=0;
    int type=0; // 0 word, 1 label
};

struct Dictionary {
    Args* args_=nullptr;
    vector<Entry> words_; // includes </s> and words, sorted by count
    vector<Entry> labels_; // sorted
    int64_t ntokens_=0;
    unordered_map<string,int> word2int_; // word -> idx in words_ (after sorting? need to rebuild)
    unordered_map<string,int> label2int_;
    // For bucket/subwords
    int bucket_=0;

    Dictionary(Args* a=nullptr): args_(a) {}

    int nwords() const { return words_.size(); }
    int nlabels() const { return labels_.size(); }
    int64_t ntokens() const { return ntokens_; }

    int getId(const string& w) const {
        auto it=word2int_.find(w);
        if (it==word2int_.end()) return -1;
        return it->second;
    }
    int getLabelId(const string& l) const {
        auto it=label2int_.find(l);
        if (it==label2int_.end()) return -1;
        return it->second;
    }
    string getWord(int i) const { return words_[i].word; }
    string getLabel(int i) const { return labels_[i].word; }

    void readFromFile(const string& filename) {
        ifstream in(filename);
        if (!in.is_open()) throw invalid_argument(filename+" cannot be opened for training!");
        unordered_map<string,int64_t> wc;
        unordered_map<string,int64_t> lc;
        vector<string> wordOrder;
        vector<string> labelOrder;
        wordOrder.reserve(10000);
        labelOrder.reserve(100);
        // Pre-insert </s> ?
        wc["</s>"]=0;
        wordOrder.push_back("</s>");
        string line;
        int64_t nlines=0;
        while (getline(in, line)) {
            nlines++;
            wc["</s>"]++;
            // split by whitespace (space, tab, etc. using istringstream)
            istringstream iss(line);
            string tok;
            while (iss >> tok) {
                if (tok.size()>=args_->label.size() && tok.compare(0,args_->label.size(),args_->label)==0) {
                    auto it=lc.find(tok);
                    if (it==lc.end()) { lc[tok]=1; labelOrder.push_back(tok); }
                    else it->second++;
                } else {
                    auto it=wc.find(tok);
                    if (it==wc.end()) { wc[tok]=1; wordOrder.push_back(tok); }
                    else it->second++;
                }
            }
        }
        ntokens_=0;
        for (auto &p: wc) ntokens_+=p.second;
        for (auto &p: lc) ntokens_+=p.second;
        // Filter by minCount
        struct Tmp { string w; int64_t c; };
        vector<Tmp> wtmp;
        for (auto &w: wordOrder) {
            int64_t c = wc[w];
            if (c >= args_->minCount) wtmp.push_back({w,c});
        }
        vector<Tmp> ltmp;
        for (auto &w: labelOrder) {
            int64_t c = lc[w];
            if (c >= args_->minCountLabel) ltmp.push_back({w,c});
        }
        if (wtmp.empty()) {
            // Check if labels also empty? Original throws "Empty vocabulary..."
            throw invalid_argument("Empty vocabulary. Try a smaller -minCount value.");
        }
        // Sort by count descending using std::sort (unstable) to match original
        sort(wtmp.begin(), wtmp.end(), [](const Tmp& a, const Tmp& b){ return a.c > b.c; });
        sort(ltmp.begin(), ltmp.end(), [](const Tmp& a, const Tmp& b){ return a.c > b.c; });
        words_.clear(); labels_.clear();
        for (auto &t: wtmp) words_.push_back({t.w, t.c, 0});
        for (auto &t: ltmp) labels_.push_back({t.w, t.c, 1});
        // Build maps
        word2int_.clear(); label2int_.clear();
        for (size_t i=0;i<words_.size();i++) word2int_[words_[i].word]=i;
        for (size_t i=0;i<labels_.size();i++) label2int_[labels_[i].word]=i;
        // Bucket handling: if no ngrams, bucket=0 else as specified
        if (args_->wordNgrams<=1 && args_->minn==0 && args_->maxn==0) bucket_=0;
        else bucket_=args_->bucket;
    }

    vector<string> getSubwords(const string& word) const {
        vector<string> res;
        if (args_->minn==0 || args_->maxn==0) return res;
        if ((int)word.size() < args_->minn) return res;
        string ext = "<"+word+">";
        for (size_t i=0;i<ext.size();i++) {
            for (int n=args_->minn; n<=args_->maxn && i+n<=ext.size(); n++) {
                res.push_back(ext.substr(i,n));
            }
        }
        return res;
    }
    // Get word ngrams (bigrams etc.) for supervised? For line tokens
    // For training/inference, input indices are word ids + hashed ngrams
    vector<int> getInputIndices(const vector<string>& words) const {
        // words are already filtered? Includes </s>? Caller should include </s>
        vector<int> ids;
        for (auto &w: words) {
            int id=getId(w);
            if (id>=0) ids.push_back(id);
            // subwords
            if (bucket_>0 && args_->minn>0) {
                auto subs=getSubwords(w);
                for (auto &s: subs) {
                    uint32_t h=fnv1a(s);
                    int idx = nwords() + (h % bucket_);
                    ids.push_back(idx);
                }
            }
        }
        // wordNgrams bigrams etc. (only for supervised? but apply generally if wordNgrams>1)
        if (args_->wordNgrams>1 && bucket_>0) {
            for (int n=2;n<=args_->wordNgrams;n++) {
                if ((int)words.size()<n) continue;
                for (size_t i=0;i+n<=words.size();i++) {
                    string ng;
                    for (int k=0;k<n;k++) { if(k) ng+=" "; ng+=words[i+k]; }
                    uint32_t h=fnv1a(ng);
                    int idx = nwords() + (h % bucket_);
                    ids.push_back(idx);
                }
            }
        } else if (args_->wordNgrams>1 && bucket_==0) {
            // Should not happen because bucket_==0 only when wordNgrams<=1 and no subwords
        }
        return ids;
    }
    int getNgramsBucket() const { return bucket_; }
    int getTotalInputSize() const { return nwords() + bucket_; }

    void save(ostream& out) const {
        int32_t size = words_.size()+labels_.size();
        int32_t nwords = words_.size();
        int32_t nlabels = labels_.size();
        int64_t ntok = ntokens_;
        int64_t extra = -1;
        out.write((char*)&size,4);
        out.write((char*)&nwords,4);
        out.write((char*)&nlabels,4);
        out.write((char*)&ntok,8);
        out.write((char*)&extra,8);
        for (auto &e: words_) {
            out.write(e.word.c_str(), e.word.size()+1);
            out.write((char*)&e.count,8);
            int8_t t=e.type;
            out.write((char*)&t,1);
        }
        for (auto &e: labels_) {
            out.write(e.word.c_str(), e.word.size()+1);
            out.write((char*)&e.count,8);
            int8_t t=e.type;
            out.write((char*)&t,1);
        }
    }
    void load(istream& in, const string& modelPath) {
        int32_t size,nwords,nlabels;
        int64_t ntok,extra;
        if(!in.read((char*)&size,4)) throw invalid_argument(modelPath+" has wrong file format!");
        if(!in.read((char*)&nwords,4)) throw invalid_argument(modelPath+" has wrong file format!");
        if(!in.read((char*)&nlabels,4)) throw invalid_argument(modelPath+" has wrong file format!");
        if(!in.read((char*)&ntok,8)) throw invalid_argument(modelPath+" has wrong file format!");
        if(!in.read((char*)&extra,8)) throw invalid_argument(modelPath+" has wrong file format!");
        // Basic validation: magic already checked, but check sizes
        if (size<0 || nwords<0 || nlabels<0 || size!=nwords+nlabels) throw invalid_argument(modelPath+" has wrong file format!");
        words_.clear(); labels_.clear();
        word2int_.clear(); label2int_.clear();
        ntokens_=ntok;
        for (int i=0;i<size;i++) {
            string w;
            char c;
            // read null-terminated string
            w.clear();
            while(in.get(c)) { if(c=='\0') break; w.push_back(c); if(w.size()>10000) throw invalid_argument(modelPath+" has wrong file format!"); }
            if(!in) throw invalid_argument(modelPath+" has wrong file format!");
            int64_t cnt; int8_t typ;
            if(!in.read((char*)&cnt,8)) throw invalid_argument(modelPath+" has wrong file format!");
            if(!in.read((char*)&typ,1)) throw invalid_argument(modelPath+" has wrong file format!");
            Entry e{w,cnt,typ};
            if (typ==0) { word2int_[w]=words_.size(); words_.push_back(e); }
            else if (typ==1) { label2int_[w]=labels_.size(); labels_.push_back(e); }
            else throw invalid_argument(modelPath+" has wrong file format!");
        }
        if ((int)words_.size()!=nwords || (int)labels_.size()!=nlabels) throw invalid_argument(modelPath+" has wrong file format!");
        if (args_) {
            if (args_->wordNgrams<=1 && args_->minn==0 && args_->maxn==0) bucket_=0;
            else bucket_=args_->bucket;
            // But when loading, bucket is from args (already loaded). For supervised with no ngrams, args bucket is 0, so bucket_=0. Good.
            // For models with bucket, use args bucket.
        }
    }
};

