// ============ Model ============
struct Model {
    Args* args_=nullptr;
    Dictionary* dict_=nullptr;
    Matrix input_, output_;
    // For hs: tree? For ns: negative table? We'll implement ns with uniform sampling for simplicity
    vector<int> negTable_;
    mt19937 rng_;
    Model(Args* a=nullptr, Dictionary* d=nullptr):args_(a),dict_(d){}
    void init() {
        int64_t inSize = dict_->getTotalInputSize();
        int64_t outSize;
        if(args_->model=="sup") outSize=dict_->nlabels();
        else outSize=dict_->nwords();
        // Handle bucket for output? For sup, output is labels only. For sg/cbow, output is words.
        // For hs, output size different? We'll use same.
        // Allocate (may throw bad_alloc for invalid dim)
        input_ = Matrix(inSize, args_->dim);
        output_ = Matrix(outSize, args_->dim);
        // Init with uniform [-1/dim, 1/dim] using minstd_rand with seed (0->1)
        int s = args_->seed==0?1:args_->seed;
        minstd_rand gen(s);
        uniform_real_distribution<float> dist(-1.0f/args_->dim, 1.0f/args_->dim);
        // Actually original uses minstd_rand directly? We'll use it
        for(auto &v: input_.data_) v = dist(gen);
        for(auto &v: output_.data_) v = 0; // output zero init? Original output zero?
        // Build neg table for ns: unigram^0.75
        if(args_->loss=="ns") buildNegTable();
    }
    void buildNegTable() {
        int n = (args_->model=="sup")? dict_->nlabels() : dict_->nwords();
        // Use word counts for table? For sup, label counts? For sg, word counts?
        vector<int64_t> counts;
        if(args_->model=="sup") { for(auto &e: dict_->labels_) counts.push_back(e.count); }
        else { for(auto &e: dict_->words_) counts.push_back(e.count); }
        double sum=0; for(auto c:counts) sum+=pow(c,0.75);
        negTable_.reserve(1000000);
        // Fill 1M entries
        for(int i=0;i<(int)counts.size();i++) {
            double p = pow(counts[i],0.75)/sum;
            int nfill = int(p*1000000);
            for(int k=0;k<nfill;k++) negTable_.push_back(i);
        }
        if(negTable_.empty()) for(int i=0;i<(int)counts.size();i++) negTable_.push_back(i);
    }
    int getNegative(int target, mt19937& rng) {
        uniform_int_distribution<size_t> dist(0,negTable_.size()-1);
        int v=negTable_[dist(rng)];
        return v;
    }
    static float sigmoid(float x){ if(x<-10) return 0; if(x>10) return 1; return 1/(1+exp(-x)); }
    // Train supervised softmax one example
    float trainSupervised(const vector<int>& inputIds, int label, float lr, mt19937& rng) {
        // Compute hidden = avg of input vectors
        int dim=args_->dim;
        vector<float> hidden(dim,0);
        for(int id: inputIds) {
            // id may be >= input_.m_? Should be < inSize
            for(int j=0;j<dim;j++) hidden[j]+=input_.data_[id*dim+j];
        }
        float inv = 1.0f/inputIds.size();
        for(int j=0;j<dim;j++) hidden[j]*=inv;
        // Compute scores = hidden * output
        int nlabels=dict_->nlabels();
        vector<float> scores(nlabels);
        for(int i=0;i<nlabels;i++) scores[i]=output_.dotRow(hidden,i);
        float loss=0;
        if(args_->loss=="softmax") {
            float maxs=*max_element(scores.begin(),scores.end());
            double sum=0; for(auto s:scores) sum+=exp(s-maxs);
            double logsum=maxs+log(sum);
            loss = -(scores[label]-logsum);
            // grad
            for(int i=0;i<nlabels;i++) {
                float p = exp(scores[i]-maxs)/sum;
